1	package registrymgr
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"log"
10		"net/http"
11		"net/url"
12		"strings"
13		"time"
14	
15		"github.com/anthnel/devdesk/internal/oci"
16	)
17	
18	func init() {
19		Register(&NexusDetector{})
20	}
21	
22	// NexusDetector handles Sonatype Nexus Repository Manager group repositories.
23	// Two URL formats are supported:
24	//  1. Path-based:   https://nexus.example.com/repository/docker-group
25	//  2. Subdomain:    nexus-docker-group.example.com  (requires info.ManagementURL)
26	//
27	// Which one applies is read from the URL. Whether this detector runs at all is
28	// not: that is the declared provider's decision (§3.8, decision F).
29	type NexusDetector struct{}
30	
31	// maxNexusResponse bounds what one Nexus reply may take in memory. The replies
32	// are small JSON documents (a repository and the names of its members); the
33	// figure follows the reasoning of the catalog page cap and is not measured.
34	const maxNexusResponse = 1 << 20
35	
36	// errEmptyReply, errNoRepositoryType and errNoGroupDocument mark a 200 reply
37	// that is not a repository (or group) document. All fail the discovery: reading
38	// any of them as "not a group" would be cached (D23) and erase the members last
39	// known.
40	var (
41		errEmptyReply       = errors.New("empty reply")
42		errNoRepositoryType = errors.New("reply names no repository type")
43		errNoGroupDocument  = errors.New("reply is not a group document")
44	)
45	
46	// nexusHTTPClient refuses a redirect to another origin, so the account of the
47	// registry is never sent to a host it was not given for.
48	var nexusHTTPClient = &http.Client{Timeout: 8 * time.Second, CheckRedirect: oci.RefuseOffOriginRedirect}
49	
50	// Provider returns the provider this detector serves.
51	func (n *NexusDetector) Provider() string { return ProviderNexus }
52	
53	// DetectGroup calls the Nexus REST API to determine whether the registry points
54	// to a group repository and, if so, returns its member repositories.
55	//
56	// Returns nil, nil when the manager answered and the repository is not a group,
57	// a non-nil empty list for a group it listed with no member, and an error when it
58	// could not be asked or refused to list the members (a *MembersRefusedError,
59	// errors.Is ErrMembersRefused). Those are not the same thing: the caller caches
60	// the settled answers and must not cache an error, or one unreachable minute (or
61	// one refused account) erases what was last known (D23).
62	func (n *NexusDetector) DetectGroup(ctx context.Context, info RegistryInfo) ([]GroupMember, error) {
63		// Resolve which URL to use for the Nexus API call.
64		apiBase := info.ManagementURL
65		if apiBase == "" {
66			apiBase = info.URL
67		}
68	
69		host, repoName, err := parseNexusURL(apiBase)
70		if err != nil {
71			// Not an error: a URL that is not a Nexus repository path is a settled
72			// answer, not a failure to reach one.
73			// The cause only: a URL that does not parse may hold a password, and
74			// url.Error repeats it whole.
75			var ue *url.Error
76			if errors.As(err, &ue) {
77				err = ue.Err
78			}
79			log.Printf("INFO [registrymgr/nexus] cannot parse Nexus URL: %v", err)
80			return nil, nil
81		}
82	
83		hasAuth := info.Username != "" && info.Password != ""
84		log.Printf("INFO [registrymgr/nexus] detecting group for %q (auth=%v)", repoName, hasAuth)
85	
86		// Step 1: generic endpoint — confirms this repo is a group, gets its format,
87		// and may already include memberNames in the attributes field (no admin privilege needed).
88		repoType, repoFormat, members, err := n.fetchRepoMeta(ctx, host, repoName, info)
89		if err != nil {
90			return nil, err
91		}
92		if repoType != "group" {
93			return nil, nil
94		}
95	
96		if len(members) > 0 {
97			log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from generic endpoint)", repoName, repoFormat, len(members))
98			return members, nil
99		}
100	
101		// Step 2: format-specific endpoint — requires nx-repository-admin privilege
102		// but returns memberNames reliably on Nexus instances that support it.
103		members, err = n.fetchGroupMembers(ctx, host, repoName, repoFormat, info)
104		if err != nil {
105			return nil, err
106		}
107		log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from format endpoint)", repoName, repoFormat, len(members))
108		return members, nil
109	}
110	
111	// fetchRepoMeta calls the generic /v1/repositories/{name} endpoint.
112	// Returns type, format and any memberNames found in attributes, or an error when
113	// the manager could not be asked.
114	// Some Nexus deployments include memberNames in attributes.group without requiring admin privilege.
115	func (n *NexusDetector) fetchRepoMeta(ctx context.Context, host, repoName string, info RegistryInfo) (repoType, format string, members []GroupMember, err error) {
116		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s", host, repoName)
117		body, err := n.nexusGET(ctx, endpoint, info)
118		if err != nil {
119			log.Printf("INFO [registrymgr/nexus] meta unreachable %q: %v", endpoint, err)
120			return "", "", nil, fmt.Errorf("reading %s: %w", endpoint, err)
121		}
122		if len(bytes.TrimSpace(body)) == 0 {
123			log.Printf("INFO [registrymgr/nexus] meta %q: empty reply", repoName)
124			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errEmptyReply)
125		}
126		var result struct {
127			Type   string `json:"type"`
128			Format string `json:"format"`
129			Group  struct {
130				MemberNames []string `json:"memberNames"`
131			} `json:"group"`
132			Attributes struct {
133				Group struct {
134					MemberNames []string `json:"memberNames"`
135				} `json:"group"`
136			} `json:"attributes"`
137		}
138		if err := json.Unmarshal(body, &result); err != nil {
139			log.Printf("INFO [registrymgr/nexus] meta parse error for %q: %v", repoName, err)
140			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, err)
141		}
142		if result.Type == "" {
143			// Valid JSON that is not a repository document: `{}`, `null`.
144			log.Printf("INFO [registrymgr/nexus] meta %q: reply names no repository type", repoName)
145			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errNoRepositoryType)
146		}
147		log.Printf("INFO [registrymgr/nexus] meta %q: type=%q format=%q", repoName, result.Type, result.Format)
148	
149		// Collect memberNames from whichever field Nexus populated.
150		rawNames := result.Group.MemberNames
151		if len(rawNames) == 0 {
152			rawNames = result.Attributes.Group.MemberNames
153		}
154		members = memberList(info.URL, rawNames)
155		return result.Type, result.Format, members, nil
156	}
157	
158	// fetchGroupMembers calls the format-specific group endpoint which reliably
159	// includes memberNames: GET /v1/repositories/{format}/group/{name}
160	// Requires nx-repository-admin privilege; falls back to anonymous when credentials fail.
161	//
162	// It returns a settled listing (non-nil, possibly empty) or an error, never a
163	// silent "no members": a 401 or 403 is a *MembersRefusedError, anything else that
164	// goes wrong is returned as it is. The caller caches the first and must not cache
165	// the second (D23).
166	//
167	// The first attempt decides. The anonymous retry (D156) only changes the outcome
168	// by succeeding: whatever it gets otherwise, the account was refused and that is
169	// the actionable fact.
170	func (n *NexusDetector) fetchGroupMembers(ctx context.Context, host, repoName, format string, info RegistryInfo) ([]GroupMember, error) {
171		if format == "" {
172			format = "docker"
173		}
174		// The format comes from the server: it stays one path segment.
175		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s/group/%s", host, url.PathEscape(format), repoName)
176		body, err := n.nexusGET(ctx, endpoint, info)
177		if err != nil {
178			firstErr := err
179			// When auth is present but the request fails, retry anonymously.
180			// Some Nexus instances allow anonymous read of the group admin endpoint.
181			// A refused redirect to another origin is not such a failure: the
182			// detection stops there (DEVDESK-412), no silent anonymous retry.
183			if info.Username != "" && info.Password != "" && !errors.Is(err, oci.ErrOffOriginRedirect) {
184				anonInfo := RegistryInfo{URL: info.URL, ManagementURL: info.ManagementURL}
185				body, err = n.nexusGET(ctx, endpoint, anonInfo)
186				if err != nil {
187					log.Printf("INFO [registrymgr/nexus] anonymous retry for %q failed: %v", repoName, err)
188				}
189			}
190			if err != nil {
191				return nil, membersFailure(host, repoName, endpoint, firstErr, info.Username != "" && info.Password != "")
192			}
193		}
194		names, err := parseGroupMembers(body)
195		if err != nil {
196			log.Printf("INFO [registrymgr/nexus] members %q: %v", repoName, err)
197			return nil, fmt.Errorf("reading the members of group %q: %w", repoName, err)
198		}
199		return memberList(info.URL, names), nil
200	}
201	
202	// membersFailure logs and types the failure of the first attempt on the format
203	// endpoint: a refusal when the manager refused the account, the error itself
204	// otherwise. The returned error holds the group and the status, never the URL.
205	func membersFailure(host, repoName, endpoint string, err error, hasAuth bool) error {
206		if status, ok := refusedStatus(err); ok {
207			log.Printf("INFO [registrymgr/nexus] members refused %q: %v — account may lack nx-repository-admin privilege; run 'docker login %s' with an admin account", endpoint, err, host)
208			return &MembersRefusedError{Group: repoName, Status: status, Anonymous: !hasAuth, Cause: err}
209		}
210		if errors.Is(err, oci.ErrOffOriginRedirect) {
211			// The advice above is for an account Nexus refused, not for this.
212			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — redirect to another origin refused (the registry URL may need to be the one Nexus serves)", endpoint, err)
213		} else {
214			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v", endpoint, err)
215		}
216		return fmt.Errorf("reading the members of group %q: %w", repoName, err)
217	}
218	
219	// parseGroupMembers reads the member names of a format-endpoint reply. A document
220	// is a `group` object carrying a `memberNames` key, an empty list included: an
221	// empty body, `null`, `{}` or a group without the key is not one, and reading it
222	// as "no members" would be cached over what was last known.
223	func parseGroupMembers(body []byte) ([]string, error) {
224		if len(bytes.TrimSpace(body)) == 0 {
225			return nil, errEmptyReply
226		}
227		var doc struct {
228			Group *struct {
229				MemberNames []string `json:"memberNames"`
230			} `json:"group"`
231		}
232		if err := json.Unmarshal(body, &doc); err != nil {
233			return nil, fmt.Errorf("parsing the reply: %w", err)
234		}
235		if doc.Group == nil || doc.Group.MemberNames == nil {
236			return nil, errNoGroupDocument
237		}
238		return doc.Group.MemberNames, nil
239	}
240	
241	// refusedStatus reports the status of a management API refusal: 401 or 403 from
242	// the manager itself, not from anything in front of it.
243	func refusedStatus(err error) (int, bool) {
244		var se *oci.StatusError
245		if !errors.As(err, &se) || se.Source != oci.SourceManagementAPI {
246			return 0, false
247		}
248		if se.Code != http.StatusUnauthorized && se.Code != http.StatusForbidden {
249			return 0, false
250		}
251		return se.Code, true
252	}
253	
254	// memberList turns the names a group declares into addresses.
255	func memberList(dockerURL string, names []string) []GroupMember {
256		members := make([]GroupMember, 0, len(names))
257		for _, name := range names {
258			url, prefix := memberAddress(dockerURL, name)
259			members = append(members, GroupMember{
260				Alias:      cleanMemberAlias(name),
261				URL:        url,
262				RepoPrefix: prefix,
263			})
264		}
265		return members
266	}
267	
268	// memberAddress decides how one member of a group is reached, from the URL the
269	// group itself is pulled from.
270	//
271	// A group written as a path prefix — `host/repository/<group>` — is an instance
272	// serving its Docker repositories that way, so its members are reached the same
273	// way: the host, with the member's name in front of the repository. That pair is
274	// consistent by construction, because browse and pull build the same path from
275	// it.
276	//
277	// Anything else is a connector of the group's own — a dedicated port, a
278	// subdomain — and says nothing about a member. Which of those a repository
279	// answers on is a setting on that repository (`docker.httpPort`,
280	// `docker.httpsPort`, `docker.subdomain`), and the endpoint carrying it is
281	// refused to an ordinary pull account. So nothing is claimed: the member is
282	// offered at the group's own address with no prefix, which browses to nothing
283	// visibly rather than pulling to nothing plausibly (§3.18).
284	func memberAddress(dockerURL, memberName string) (url, prefix string) {
285		host, _, err := parseNexusURL(dockerURL)
286		if err != nil {
287			return dockerURL, ""
288		}
289		// parseNexusURL supplies https:// for a URL written without a scheme. The
290		// group's own spelling is what the rest of the application is keyed on, so
291		// it is kept rather than normalised here.
292		if !strings.Contains(strings.ToLower(dockerURL), "://") {
293			host = strings.TrimPrefix(host, "https://")
294		}
295		return host, memberName
296	}
297	
298	// nexusGET performs an authenticated GET and returns the response body. A status
299	// other than 200 is a *oci.StatusError from the management API: the code only, no
300	// status line, body or header. A context error stays a context error.
301	func (n *NexusDetector) nexusGET(ctx context.Context, endpoint string, info RegistryInfo) ([]byte, error) {
302		req, err := http.NewRequestWithContext(ctx, "GET", endpoint, nil)
303		if err != nil {
304			return nil, err
305		}
306		if info.Username != "" && info.Password != "" {
307			req.SetBasicAuth(info.Username, info.Password)
308		}
309		resp, err := nexusHTTPClient.Do(req)
310		if err != nil {
311			// A refused redirect comes back without the URL it pointed to, which
312			// may be signed.
313			return nil, oci.StripRedirectTarget(err)
314		}
315		defer func() { _ = resp.Body.Close() }()
316		if resp.StatusCode != http.StatusOK {
317			return nil, &oci.StatusError{Code: resp.StatusCode, Source: oci.SourceManagementAPI}
318		}
319		body, err := oci.ReadAllLimited(resp.Body, maxNexusResponse)
320		if err != nil {
321			// Which error net/http gives a body cut by a cancel varies: report the
322			// context's own.
323			if ctxErr := ctx.Err(); ctxErr != nil {
324				return nil, fmt.Errorf("read Nexus response: %w", ctxErr)
325			}
326			return nil, fmt.Errorf("read Nexus response: %w", err)
327		}
328		return body, nil
329	}
330	
331	// parseNexusURL extracts the scheme+host and repository name from a Nexus URL.
332	// e.g. "https://nexus.example.com/repository/docker-group" → ("https://nexus.example.com", "docker-group")
333	func parseNexusURL(registryURL string) (host, repoName string, err error) {
334		raw := registryURL
335		if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
336			raw = "https://" + raw
337		}
338		u, err := url.Parse(raw)
339		if err != nil {
340			return "", "", err
341		}
342		parts := strings.SplitN(strings.TrimPrefix(u.Path, "/"), "/", 3)
343		// Expected: ["repository", "<repoName>", ...]
344		if len(parts) < 2 || parts[0] != "repository" || parts[1] == "" {
345			return "", "", fmt.Errorf("not a Nexus repository path: %q", u.Path)
346		}
347		host = u.Scheme + "://" + u.Host
348		repoName = parts[1]
349		return host, repoName, nil
350	}
351	
352	// cleanMemberAlias strips common suffixes (-proxy, -hosted, -local) for a friendlier display name.
353	func cleanMemberAlias(name string) string {
354		for _, suffix := range []string{"-proxy", "-hosted", "-local"} {
355			if strings.HasSuffix(name, suffix) {
356				return name[:len(name)-len(suffix)]
357			}
358		}
359		return name
360	}
