1	package registrymgr
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"net/http"
9		"strings"
10		"sync/atomic"
11		"testing"
12		"time"
13	
14		"github.com/anthnel/devdesk/internal/oci"
15	)
16	
17	// DEVDESK-510 (NX-07): a group whose members endpoint is refused is not an empty
18	// group. The format endpoint answers one of three ways: a settled listing
19	// (possibly empty), a refusal (401/403, typed as ErrMembersRefused), or a failed
20	// discovery (everything else), and only the first may be read as "N members".
21	
22	const nexusFormatSegment = "/group/"
23	
24	// membersServer starts a Nexus whose generic endpoint says "group, no members"
25	// and whose format endpoint is the given handler. formatHits counts the requests
26	// the format endpoint received and formatAuths records their Authorization.
27	func membersServer(t *testing.T, format http.HandlerFunc) (info RegistryInfo, formatHits *atomic.Int32) {
28		t.Helper()
29		formatHits = &atomic.Int32{}
30		info, _ = nexusServer(t, func(w http.ResponseWriter, r *http.Request) {
31			if !strings.Contains(r.URL.Path, nexusFormatSegment) {
32				_, _ = io.WriteString(w, nexusGroupNoMembers)
33				return
34			}
35			formatHits.Add(1)
36			format(w, r)
37		})
38		return info, formatHits
39	}
40	
41	func status(code int) http.HandlerFunc {
42		return func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(code) }
43	}
44	
45	// wantRefused fails unless err is a members refusal with the given fields, whose
46	// cause is the management API's status error, and which leaks nothing.
47	func wantRefused(t *testing.T, members []GroupMember, err error, code int, anonymous bool) {
48		t.Helper()
49		if err == nil {
50			t.Fatalf("err = nil (members = %v), want a refusal: a refused listing is not an empty group", members)
51		}
52		if members != nil {
53			t.Errorf("members = %v, want nil on a refusal", members)
54		}
55		if !errors.Is(err, ErrMembersRefused) {
56			t.Errorf("err = %v, want errors.Is ErrMembersRefused", err)
57		}
58		var refused *MembersRefusedError
59		if !errors.As(err, &refused) {
60			t.Fatalf("err = %v (%T), want errors.As *MembersRefusedError", err, err)
61		}
62		if refused.Group != "docker-group" || refused.Status != code || refused.Anonymous != anonymous {
63			t.Errorf("refusal = {Group %q, Status %d, Anonymous %v}, want {docker-group, %d, %v}",
64				refused.Group, refused.Status, refused.Anonymous, code, anonymous)
65		}
66		var se *oci.StatusError
67		if !errors.As(err, &se) {
68			t.Fatalf("err = %v, want errors.As *oci.StatusError (the cause)", err)
69		}
70		if se.Code != code || se.Source != oci.SourceManagementAPI {
71			t.Errorf("cause = {Code %d, Source %v}, want {%d, management API}", se.Code, se.Source, code)
72		}
73		if refused.Cause == nil || !errors.As(refused.Cause, &se) {
74			t.Errorf("Cause = %v, want the *oci.StatusError", refused.Cause)
75		}
76		wantNoSecret(t, "error", err.Error())
77		if strings.Contains(err.Error(), "http://") {
78			t.Errorf("error carries a URL: %v", err)
79		}
80	}
81	
82	// wantFailedDiscovery fails unless err is a non-nil error that is not a refusal.
83	func wantFailedDiscovery(t *testing.T, members []GroupMember, err error) {
84		t.Helper()
85		if err == nil {
86			t.Fatalf("err = nil (members = %v), want a failed discovery", members)
87		}
88		if members != nil {
89			t.Errorf("members = %v, want nil on a failed discovery", members)
90		}
91		if errors.Is(err, ErrMembersRefused) {
92			t.Errorf("err = %v, is ErrMembersRefused, want a plain failure (not a refusal)", err)
93		}
94		var refused *MembersRefusedError
95		if errors.As(err, &refused) {
96			t.Errorf("err = %v, is a *MembersRefusedError, want a plain failure", err)
97		}
98		wantNoSecret(t, "error", err.Error())
99	}
100	
101	// CA1. The generic endpoint says "group" and the format endpoint refuses the
102	// account: a refusal, not "0 members". 401 and 403 alike.
103	func TestNexusRefusedMembersAreARefusalNotAnEmptyGroup(t *testing.T) {
104		for _, code := range []int{http.StatusForbidden, http.StatusUnauthorized} {
105			t.Run(fmt.Sprint(code), func(t *testing.T) {
106				info, formatHits := membersServer(t, status(code))
107	
108				members, err := (&NexusDetector{}).DetectGroup(context.Background(), info)
109	
110				wantRefused(t, members, err, code, false)
111				if got := formatHits.Load(); got != 2 {
112					t.Errorf("the format endpoint received %d requests, want 2 (account, then the anonymous retry of D156)", got)
113				}
114			})
115		}
116	}
117	
118	// CA1, anonymous. A registry with no credential is refused on the format
119	// endpoint: a refusal flagged Anonymous, and no retry (there is nothing to drop).
120	func TestNexusRefusedMembersWithoutCredentialIsAnAnonymousRefusal(t *testing.T) {
121		for _, code := range []int{http.StatusForbidden, http.StatusUnauthorized} {
122			t.Run(fmt.Sprint(code), func(t *testing.T) {
123				info, formatHits := membersServer(t, status(code))
124				info.Username, info.Password = "", ""
125	
126				members, err := (&NexusDetector{}).DetectGroup(context.Background(), info)
127	
128				wantRefused(t, members, err, code, true)
129				if got := formatHits.Load(); got != 1 {
130					t.Errorf("the format endpoint received %d requests, want exactly 1", got)
131				}
132			})
133		}
134	}
135	
136	// D156 followed by a 403 for the anonymous request too: the account was refused
137	// first and that is the verdict (Anonymous false), whatever the retry got.
138	func TestNexusRefusedAccountThenRefusedAnonymousRetryIsAnAccountRefusal(t *testing.T) {
139		info, formatHits := membersServer(t, status(http.StatusForbidden))
140	
141		members, err := (&NexusDetector{}).DetectGroup(context.Background(), info)
142	
143		wantRefused(t, members, err, http.StatusForbidden, false)
144		if got := formatHits.Load(); got != 2 {
145			t.Errorf("the format endpoint received %d requests, want 2", got)
146		}
147	}
148	
149	// The account is refused (403), the anonymous retry is answered by something
150	// else (500): the refusal is still the verdict, the retry's error is not returned.
151	func TestNexusRefusedAccountWhoseAnonymousRetryFailsIsStillARefusal(t *testing.T) {
152		info, _ := membersServer(t, func(w http.ResponseWriter, r *http.Request) {
153			if r.Header.Get("Authorization") != "" {
154				w.WriteHeader(http.StatusForbidden)
155				return
156			}
157			w.WriteHeader(http.StatusInternalServerError)
158		})
159	
160		members, err := (&NexusDetector{}).DetectGroup(context.Background(), info)
161	
162		wantRefused(t, members, err, http.StatusForbidden, false)
163	}
164	
165	// A 403 on the generic endpoint does not say the repository is a group: it stays a
166	// failed discovery, not a members refusal (pinned so it does not drift).
167	func TestNexusRefusedGenericEndpointIsNotAMembersRefusal(t *testing.T) {
168		info, _ := nexusServer(t, func(w http.ResponseWriter, _ *http.Request) {
169			w.WriteHeader(http.StatusForbidden)
