76	// The premises every verdict below rests on, read from the fixtures.
77	func TestMeasuredRESTAnswersHoldThePremises(t *testing.T) {
78		fixtures := restFixtures(t)
79	
80		// Criterion 3: the generic endpoint answers 200 to all three accounts, names
81		// the type, and carries no memberNames anywhere (so step 2 of DetectGroup is
82		// always reached for a group).
83		for _, tc := range []struct{ repo, typ string }{{restGroup, "group"}, {restHosted, "hosted"}, {restProxy, "proxy"}} {
84			for _, id := range restIdentities {
85				ex := restExchange(t, fixtures, genericFixture(tc.repo, id))
86				if ex.Status != http.StatusOK {
87					t.Errorf("%s generic as %s: status %d, want 200", tc.repo, id, ex.Status)
88				}
89				var doc struct {
90					Type  string `json:"type"`
91					Group any    `json:"group"`
92					Attrs struct {
93						Group any `json:"group"`
94					} `json:"attributes"`
95				}
96				if err := json.Unmarshal(ex.Body, &doc); err != nil {
97					t.Fatalf("%s generic as %s: %v", tc.repo, id, err)
98				}
99				if doc.Type != tc.typ {
100					t.Errorf("%s generic as %s: type %q, want %q", tc.repo, id, doc.Type, tc.typ)
101				}
102				if doc.Group != nil || doc.Attrs.Group != nil {
103					t.Errorf("%s generic as %s carries a group document: DetectGroup would stop at step 1", tc.repo, id)
104				}
105			}
106		}
107	
108		// The detailed endpoint of the group: 200 with the members for admin, 403
109		// with no body for anonymous, and 404 "Repository not found" (not 403) for the
110		// pull account (C1 of the DEVDESK-511 plan, decided by the user).
111		admin := restExchange(t, fixtures, detailedFixture(restGroup, nexusfixture.Admin))
112		if admin.Status != http.StatusOK {
113			t.Errorf("detailed as admin: status %d, want 200", admin.Status)
114		}
115		if got := memberNamesOf(t, admin.Body); !reflect.DeepEqual(got, []string{restHosted, restProxy}) {
116			t.Errorf("detailed as admin: memberNames %v, want [%s %s]", got, restHosted, restProxy)
117		}
118		anon := restExchange(t, fixtures, detailedFixture(restGroup, nexusfixture.Anonymous))
119		if anon.Status != http.StatusForbidden || len(anon.Body) != 0 {
120			t.Errorf("detailed as anonymous: %d %q, want 403 with no body", anon.Status, anon.Body)
121		}
122		pull := restExchange(t, fixtures, detailedFixture(restGroup, nexusfixture.Pull))
123		if pull.Status != http.StatusNotFound || !strings.Contains(string(pull.Body), "Repository not found") {
124			t.Errorf("detailed as pull: %d %q, want 404 \"Repository not found\"", pull.Status, pull.Body)
125		}
