2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"log"
10		"net/http"
11		"net/url"
12		"strings"
13		"time"
14	
15		"github.com/anthnel/devdesk/internal/oci"
16	)
17	
18	func init() {
19		Register(&NexusDetector{})
20	}
21	
22	// NexusDetector handles Sonatype Nexus Repository Manager group repositories.
23	// Two URL formats are supported:
24	//  1. Path-based:   https://nexus.example.com/repository/docker-group
25	//  2. Subdomain:    nexus-docker-group.example.com  (requires info.ManagementURL)
26	//
27	// Which one applies is read from the URL. Whether this detector runs at all is
28	// not: that is the declared provider's decision (§3.8, decision F).
29	type NexusDetector struct{}
30	
31	// maxNexusResponse bounds what one Nexus reply may take in memory. The replies
32	// are small JSON documents (a repository and the names of its members); the
33	// figure follows the reasoning of the catalog page cap and is not measured.
34	const maxNexusResponse = 1 << 20
35	
36	// errEmptyReply, errNoRepositoryType and errNoGroupDocument mark a 200 reply
37	// that is not a repository (or group) document. All fail the discovery: reading
38	// any of them as "not a group" would be cached (D23) and erase the members last
39	// known.
40	var (
41		errEmptyReply       = errors.New("empty reply")
42		errNoRepositoryType = errors.New("reply names no repository type")
43		errNoGroupDocument  = errors.New("reply is not a group document")
44	)
45	
46	// nexusHTTPClient refuses a redirect to another origin, so the account of the
47	// registry is never sent to a host it was not given for.
48	var nexusHTTPClient = &http.Client{Timeout: 8 * time.Second, CheckRedirect: oci.RefuseOffOriginRedirect}
49	
50	// Provider returns the provider this detector serves.
51	func (n *NexusDetector) Provider() string { return ProviderNexus }
52	
53	// DetectGroup calls the Nexus REST API to determine whether the registry points
54	// to a group repository and, if so, returns its member repositories.
55	//
56	// Returns nil, nil when the manager answered and the repository is not a group,
57	// a non-nil empty list for a group it listed with no member, and an error when it
58	// could not be asked or refused to list the members (a *MembersRefusedError,
59	// errors.Is ErrMembersRefused). Those are not the same thing: the caller caches
60	// the settled answers and must not cache an error, or one unreachable minute (or
61	// one refused account) erases what was last known (D23).
62	func (n *NexusDetector) DetectGroup(ctx context.Context, info RegistryInfo) ([]GroupMember, error) {
63		// Resolve which URL to use for the Nexus API call.
64		apiBase := info.ManagementURL
65		if apiBase == "" {
66			apiBase = info.URL
67		}
68	
69		host, repoName, err := parseNexusURL(apiBase)
70		if err != nil {
71			// Not an error: a URL that is not a Nexus repository path is a settled
72			// answer, not a failure to reach one.
73			// The cause only: a URL that does not parse may hold a password, and
74			// url.Error repeats it whole.
75			var ue *url.Error
76			if errors.As(err, &ue) {
77				err = ue.Err
78			}
79			log.Printf("INFO [registrymgr/nexus] cannot parse Nexus URL: %v", err)
80			return nil, nil
81		}
82	
83		hasAuth := info.Username != "" && info.Password != ""
84		log.Printf("INFO [registrymgr/nexus] detecting group for %q (auth=%v)", repoName, hasAuth)
85	
86		// Step 1: generic endpoint — confirms this repo is a group, gets its format,
87		// and may already include memberNames in the attributes field (no admin privilege needed).
88		repoType, repoFormat, members, err := n.fetchRepoMeta(ctx, host, repoName, info)
89		if err != nil {
90			return nil, err
91		}
92		if repoType != "group" {
93			return nil, nil
94		}
95	
96		if len(members) > 0 {
97			log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from generic endpoint)", repoName, repoFormat, len(members))
98			return members, nil
99		}
100	
101		// Step 2: format-specific endpoint — requires nx-repository-admin privilege
102		// but returns memberNames reliably on Nexus instances that support it.
103		members, err = n.fetchGroupMembers(ctx, host, repoName, repoFormat, info)
104		if err != nil {
105			return nil, err
106		}
107		log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from format endpoint)", repoName, repoFormat, len(members))
108		return members, nil
109	}
