111	// fetchRepoMeta calls the generic /v1/repositories/{name} endpoint.
112	// Returns type, format and any memberNames found in attributes, or an error when
113	// the manager could not be asked.
114	// Some Nexus deployments include memberNames in attributes.group without requiring admin privilege.
115	func (n *NexusDetector) fetchRepoMeta(ctx context.Context, host, repoName string, info RegistryInfo) (repoType, format string, members []GroupMember, err error) {
116		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s", host, repoName)
117		body, err := n.nexusGET(ctx, endpoint, info)
118		if err != nil {
119			log.Printf("INFO [registrymgr/nexus] meta unreachable %q: %v", endpoint, err)
120			return "", "", nil, fmt.Errorf("reading %s: %w", endpoint, err)
121		}
122		if len(bytes.TrimSpace(body)) == 0 {
123			log.Printf("INFO [registrymgr/nexus] meta %q: empty reply", repoName)
124			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errEmptyReply)
125		}
126		var result struct {
127			Type   string `json:"type"`
128			Format string `json:"format"`
129			Group  struct {
130				MemberNames []string `json:"memberNames"`
131			} `json:"group"`
132			Attributes struct {
133				Group struct {
134					MemberNames []string `json:"memberNames"`
135				} `json:"group"`
136			} `json:"attributes"`
137		}
138		if err := json.Unmarshal(body, &result); err != nil {
139			log.Printf("INFO [registrymgr/nexus] meta parse error for %q: %v", repoName, err)
140			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, err)
141		}
142		if result.Type == "" {
143			// Valid JSON that is not a repository document: `{}`, `null`.
144			log.Printf("INFO [registrymgr/nexus] meta %q: reply names no repository type", repoName)
145			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errNoRepositoryType)
146		}
147		log.Printf("INFO [registrymgr/nexus] meta %q: type=%q format=%q", repoName, result.Type, result.Format)
148	
149		// Collect memberNames from whichever field Nexus populated.
150		rawNames := result.Group.MemberNames
151		if len(rawNames) == 0 {
152			rawNames = result.Attributes.Group.MemberNames
153		}
154		members = memberList(info.URL, rawNames)
155		return result.Type, result.Format, members, nil
156	}
