219	// parseGroupMembers reads the member names of a format-endpoint reply. A document
220	// is a `group` object carrying a `memberNames` key, an empty list included: an
221	// empty body, `null`, `{}` or a group without the key is not one, and reading it
222	// as "no members" would be cached over what was last known.
223	func parseGroupMembers(body []byte) ([]string, error) {
224		if len(bytes.TrimSpace(body)) == 0 {
225			return nil, errEmptyReply
226		}
227		var doc struct {
228			Group *struct {
229				MemberNames []string `json:"memberNames"`
230			} `json:"group"`
231		}
232		if err := json.Unmarshal(body, &doc); err != nil {
233			return nil, fmt.Errorf("parsing the reply: %w", err)
234		}
235		if doc.Group == nil || doc.Group.MemberNames == nil {
236			return nil, errNoGroupDocument
237		}
238		return doc.Group.MemberNames, nil
239	}
