241	// refusedStatus reports the status of a management API refusal: 401 or 403 from
242	// the manager itself, not from anything in front of it.
243	func refusedStatus(err error) (int, bool) {
244		var se *oci.StatusError
245		if !errors.As(err, &se) || se.Source != oci.SourceManagementAPI {
246			return 0, false
247		}
248		if se.Code != http.StatusUnauthorized && se.Code != http.StatusForbidden {
249			return 0, false
250		}
251		return se.Code, true
252	}
