254	// memberList turns the names a group declares into addresses.
255	func memberList(dockerURL string, names []string) []GroupMember {
256		members := make([]GroupMember, 0, len(names))
257		for _, name := range names {
258			url, prefix := memberAddress(dockerURL, name)
259			members = append(members, GroupMember{
260				Alias:      cleanMemberAlias(name),
261				URL:        url,
262				RepoPrefix: prefix,
263			})
264		}
265		return members
266	}
267	
268	// memberAddress decides how one member of a group is reached, from the URL the
269	// group itself is pulled from.
270	//
271	// A group written as a path prefix — `host/repository/<group>` — is an instance
272	// serving its Docker repositories that way, so its members are reached the same
273	// way: the host, with the member's name in front of the repository. That pair is
274	// consistent by construction, because browse and pull build the same path from
275	// it.
276	//
277	// Anything else is a connector of the group's own — a dedicated port, a
278	// subdomain — and says nothing about a member. Which of those a repository
279	// answers on is a setting on that repository (`docker.httpPort`,
280	// `docker.httpsPort`, `docker.subdomain`), and the endpoint carrying it is
281	// refused to an ordinary pull account. So nothing is claimed: the member is
282	// offered at the group's own address with no prefix, which browses to nothing
283	// visibly rather than pulling to nothing plausibly (§3.18).
284	func memberAddress(dockerURL, memberName string) (url, prefix string) {
285		host, _, err := parseNexusURL(dockerURL)
286		if err != nil {
287			return dockerURL, ""
288		}
289		// parseNexusURL supplies https:// for a URL written without a scheme. The
290		// group's own spelling is what the rest of the application is keyed on, so
291		// it is kept rather than normalised here.
292		if !strings.Contains(strings.ToLower(dockerURL), "://") {
293			host = strings.TrimPrefix(host, "https://")
294		}
295		return host, memberName
296	}
297	
298	// nexusGET performs an authenticated GET and returns the response body. A status
299	// other than 200 is a *oci.StatusError from the management API: the code only, no
300	// status line, body or header. A context error stays a context error.
301	func (n *NexusDetector) nexusGET(ctx context.Context, endpoint string, info RegistryInfo) ([]byte, error) {
302		req, err := http.NewRequestWithContext(ctx, "GET", endpoint, nil)
303		if err != nil {
304			return nil, err
305		}
306		if info.Username != "" && info.Password != "" {
307			req.SetBasicAuth(info.Username, info.Password)
308		}
309		resp, err := nexusHTTPClient.Do(req)
310		if err != nil {
311			// A refused redirect comes back without the URL it pointed to, which
312			// may be signed.
313			return nil, oci.StripRedirectTarget(err)
314		}
315		defer func() { _ = resp.Body.Close() }()
316		if resp.StatusCode != http.StatusOK {
317			return nil, &oci.StatusError{Code: resp.StatusCode, Source: oci.SourceManagementAPI}
318		}
319		body, err := oci.ReadAllLimited(resp.Body, maxNexusResponse)
320		if err != nil {
321			// Which error net/http gives a body cut by a cancel varies: report the
322			// context's own.
323			if ctxErr := ctx.Err(); ctxErr != nil {
324				return nil, fmt.Errorf("read Nexus response: %w", ctxErr)
325			}
326			return nil, fmt.Errorf("read Nexus response: %w", err)
327		}
328		return body, nil
329	}
330	
331	// parseNexusURL extracts the scheme+host and repository name from a Nexus URL.
332	// e.g. "https://nexus.example.com/repository/docker-group" → ("https://nexus.example.com", "docker-group")
333	func parseNexusURL(registryURL string) (host, repoName string, err error) {
334		raw := registryURL
335		if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
336			raw = "https://" + raw
337		}
338		u, err := url.Parse(raw)
339		if err != nil {
340			return "", "", err
341		}
342		parts := strings.SplitN(strings.TrimPrefix(u.Path, "/"), "/", 3)
343		// Expected: ["repository", "<repoName>", ...]
344		if len(parts) < 2 || parts[0] != "repository" || parts[1] == "" {
345			return "", "", fmt.Errorf("not a Nexus repository path: %q", u.Path)
346		}
347		host = u.Scheme + "://" + u.Host
348		repoName = parts[1]
349		return host, repoName, nil
350	}
351	
352	// cleanMemberAlias strips common suffixes (-proxy, -hosted, -local) for a friendlier display name.
353	func cleanMemberAlias(name string) string {
354		for _, suffix := range []string{"-proxy", "-hosted", "-local"} {
355			if strings.HasSuffix(name, suffix) {
356				return name[:len(name)-len(suffix)]
357			}
358		}
359		return name
360	}
